import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { errorDetailSchema, type ErrorDetail } from "./error-detail.js";

export type EvaluateMappingTemplateResponse = {
  /** The mapping template; this can be a request or response template. */
  evaluationResult?: string;
  error?: ErrorDetail;
  /**
   * A list of logs that were generated by calls to util.log.info and util.log.error in the
   * evaluated code.
   */
  logs?: string[];
  /**
   * An object available inside each resolver and function handler. A single stash object lives
   * through a single resolver run. Therefore, you can use the stash to pass arbitrary data across
   * request and response handlers and across functions in a pipeline resolver.
   */
  stash?: string;
  /** The list of runtime errors that are added to the GraphQL operation response. */
  outErrors?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const evaluateMappingTemplateResponseSchema: Schema<EvaluateMappingTemplateResponse> =
  s.object<EvaluateMappingTemplateResponse>(
    {
      evaluationResult: s.optional(s.string()),
      error: s.optional(s.lazy(() => errorDetailSchema)),
      logs: s.optional(s.array(s.string())),
      stash: s.optional(s.string()),
      outErrors: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
